import Foundation

/// What clipboard history refuses to record (#45). The shell asks before it
/// reads a single byte of the pasteboard, and the reducer checks again.
enum ClipboardPolicy {
    /// Types apps put on the pasteboard to say "don't keep this":
    /// nspasteboard.org's marker types, and what some password managers use.
    static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
        "com.agilebits.onepassword",
    ]

    /// Apps whose copies are skipped until the user changes the list.
    static let defaultExcludedApps: [String] = [
        "com.apple.keychainaccess",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.agilebits.onepassword-osx",
        "com.bitwarden.desktop",
        "org.keepassxc.keepassxc",
        "com.dashlane.dashlanephonefinal",
    ]

    /// Longest text kept. Longer copies are skipped rather than cut, because
    /// pasting half of something back would be worse than not having it.
    static let maxTextBytes = 100_000
    static let maxImageBytes = 5_000_000

    enum SkipReason: Equatable, Sendable {
        case privateType
        case excludedApp
    }

    static func skipReason(types: [String], sourceBundleID: String?, excludedApps: Set<String>) -> SkipReason? {
        if types.contains(where: privateTypes.contains) { return .privateType }
        if let sourceBundleID, excludedApps.contains(sourceBundleID) { return .excludedApp }
        return nil
    }
}

/// Filtering and ordering for the list.
enum ClipboardSearch {
    /// Every word of the query must appear in the text or the source app's
    /// name, ignoring case and accents. An empty query keeps everything.
    static func filter(_ entries: [ClipboardEntry], query: String) -> [ClipboardEntry] {
        let words = query.split(whereSeparator: \.isWhitespace).map(String.init)
        guard !words.isEmpty else { return entries }
        return entries.filter { entry in
            words.allSatisfy { word in
                entry.text.range(of: word, options: [.caseInsensitive, .diacriticInsensitive]) != nil
                    || entry.sourceName?.range(of: word, options: [.caseInsensitive, .diacriticInsensitive]) != nil
            }
        }
    }

    /// Pinned first, then the rest; each keeps its newest-first order.
    static func displayOrder(_ entries: [ClipboardEntry]) -> [ClipboardEntry] {
        entries.filter(\.isPinned) + entries.filter { !$0.isPinned }
    }
}
